using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System.ComponentModel.DataAnnotations;
namespace AcxiomCRM.Controllers;
public class UserEdit{[Required]public string FullName{get;set;}="";[Required,EmailAddress]public string Email{get;set;}="";[Required,RegularExpression("^(Admin|Manager|SalesExecutive)$")]public string Role{get;set;}="SalesExecutive";public bool IsActive{get;set;}=true;public string? ManagerId{get;set;}[DataType(DataType.Password)]public string? Password{get;set;}}
[Authorize(Roles="Admin")]public class UsersController(UserManager<ApplicationUser> users,AuditService audit):Controller{
public async Task<IActionResult> Index(string? q){var list=await users.Users.Where(x=>q==null||x.Email!.Contains(q)||x.FullName.Contains(q)).OrderBy(x=>x.FullName).ToListAsync();var rows=new List<(ApplicationUser,string)>();foreach(var u in list)rows.Add((u,string.Join(",",await users.GetRolesAsync(u))));return View(rows);}
public async Task<IActionResult> Edit(string? id){ViewBag.Id=id;ViewBag.Managers=await users.GetUsersInRoleAsync("Manager");if(id==null)return View(new UserEdit());var u=await users.FindByIdAsync(id);if(u==null)return NotFound();return View(new UserEdit{FullName=u.FullName,Email=u.Email!,Role=(await users.GetRolesAsync(u)).FirstOrDefault()??"SalesExecutive",IsActive=u.IsActive,ManagerId=u.ManagerId});}
[HttpPost]public async Task<IActionResult> Edit(string? id,UserEdit input){ViewBag.Id=id;ViewBag.Managers=await users.GetUsersInRoleAsync("Manager");var u=id==null?new ApplicationUser():await users.FindByIdAsync(id);if(u==null)return NotFound();var oldRole=id==null?null:(await users.GetRolesAsync(u)).FirstOrDefault();if(input.ManagerId!=null&&!((IList<ApplicationUser>)ViewBag.Managers).Any(x=>x.Id==input.ManagerId&&x.IsActive))ModelState.AddModelError("","Invalid manager.");if(oldRole=="Admin"&&(!input.IsActive||input.Role!="Admin")&&(await users.GetUsersInRoleAsync("Admin")).Count(x=>x.IsActive)<=1)ModelState.AddModelError("","Cannot remove the last active administrator.");if(id==null&&string.IsNullOrWhiteSpace(input.Password))ModelState.AddModelError("Password","Password required.");if(!ModelState.IsValid)return View(input);u.FullName=input.FullName;u.Email=input.Email;u.UserName=input.Email;u.IsActive=input.IsActive;u.ManagerId=input.Role=="SalesExecutive"?input.ManagerId:null;var r=id==null?await users.CreateAsync(u,input.Password!):await users.UpdateAsync(u);if(r.Succeeded&&oldRole!=input.Role){if(oldRole!=null)r=await users.RemoveFromRoleAsync(u,oldRole);if(r.Succeeded)r=await users.AddToRoleAsync(u,input.Role);}if(r.Succeeded&&id!=null&&!string.IsNullOrWhiteSpace(input.Password)){var token=await users.GeneratePasswordResetTokenAsync(u);r=await users.ResetPasswordAsync(u,token,input.Password);}if(r.Succeeded){await users.UpdateSecurityStampAsync(u);await audit.Write(oldRole!=input.Role?"Role Change":"Update","User",u.Id);return RedirectToAction(nameof(Index));}foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return View(input);}
[HttpPost]public async Task<IActionResult> Unlock(string id){var u=await users.FindByIdAsync(id);if(u==null)return NotFound();await users.SetLockoutEndDateAsync(u,null);await users.ResetAccessFailedCountAsync(u);await audit.Write("Unlock","User",id);return RedirectToAction(nameof(Index));}
}
